package org.telegram.ui;
import android.content.Context;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import android.widget.SeekBar;
import java.util.ArrayList;
import org.telegram.messenger.*;
import org.telegram.messenger.music.*;
import org.telegram.ui.ActionBar.*;
import org.telegram.ui.Components.*;
import static org.telegram.ui.Components.ClaudMusicStyle.*;

/** Full-screen native player; the same foreground service owns every control. */
public final class ClaudSoundCloudPlayerActivity extends BaseFragment {
 private TextView title,artist,art,elapsed,total,status,nextName,nextArtist,nextArt;private ImageView play,favorite;private SeekBar seek;private LinearLayout nextCard;private boolean active,dragging;private String shown="",shownNext="";
 private final android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());private final Runnable tick=new Runnable(){public void run(){if(!active)return;refresh();handler.postDelayed(this,500);}};
 @Override public View createView(Context c){actionBar.setTitle("Сейчас играет");actionBar.setBackButtonImage(R.drawable.ic_ab_back);actionBar.setBackgroundColor(BG);actionBar.setTitleColor(TEXT);actionBar.setItemsColor(TEXT,false);actionBar.setActionBarMenuOnItemClick(new ActionBar.ActionBarMenuOnItemClick(){public void onItemClick(int id){if(id==-1)finishFragment();}});
  ScrollView scroll=new ScrollView(c);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(false);scroll.setBackgroundColor(BG);LinearLayout box=new LinearLayout(c);box.setOrientation(1);box.setPadding(dp(28),dp(20),dp(28),dp(24));scroll.addView(box);
  art=cover(c,18,null);art.setElevation(dp(12));int coverSize=Math.min(Math.min(dp(350),c.getResources().getDisplayMetrics().widthPixels-dp(56)),(int)(c.getResources().getDisplayMetrics().heightPixels*.39f));LinearLayout.LayoutParams coverLp=new LinearLayout.LayoutParams(coverSize,coverSize);coverLp.gravity=Gravity.CENTER_HORIZONTAL;box.addView(art,coverLp);
  LinearLayout meta=new LinearLayout(c);meta.setGravity(Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams ml=new LinearLayout.LayoutParams(-1,-2);ml.topMargin=dp(28);box.addView(meta,ml);LinearLayout names=new LinearLayout(c);names.setOrientation(1);meta.addView(names,new LinearLayout.LayoutParams(0,-2,1));title=text(c,"",27,true,TEXT);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);names.addView(title);artist=text(c,"",16,false,MUTED);artist.setPadding(0,dp(9),0,dp(8));artist.setSingleLine(true);names.addView(artist);artist.setOnClickListener(v->{SoundCloudPublic.Track t=SoundCloudPlayback.current;if(t==null)return;SoundCloudPublic.Artist a=SoundCloudPublic.artistFor(t);if(a!=null)presentFragment(new ClaudSoundCloudBrowseActivity("artist",a.id,a.name));});favorite=icon(c,"heart","Любимые треки",ACCENT,()->{SoundCloudPublic.Track t=SoundCloudPlayback.current;if(t==null)return;if(SoundCloudLibrary.contains(currentAccount,"favorites",t.id))SoundCloudLibrary.remove(currentAccount,"favorites",t.id);else SoundCloudLibrary.add(currentAccount,"favorites",t);refresh();});meta.addView(favorite,new LinearLayout.LayoutParams(dp(48),dp(48)));
  status=text(c,"SoundCloud",11,false,MUTED);status.setPadding(0,dp(2),0,dp(12));box.addView(status);
  seek=new SeekBar(c);seek.setMax(1000);seek.setPadding(0,0,0,0);GradientDrawable track=shape(LINE,2),filled=shape(ACCENT,2);ClipDrawable clip=new ClipDrawable(filled,Gravity.LEFT,ClipDrawable.HORIZONTAL);LayerDrawable layers=new LayerDrawable(new Drawable[]{track,clip});layers.setId(0,android.R.id.background);layers.setId(1,android.R.id.progress);seek.setProgressDrawable(layers);seek.setMinimumHeight(dp(3));if(android.os.Build.VERSION.SDK_INT>=29)seek.setMaxHeight(dp(3));GradientDrawable thumb=shape(TEXT,8);thumb.setSize(dp(8),dp(8));seek.setThumb(thumb);seek.setThumbOffset(dp(4));box.addView(seek,new LinearLayout.LayoutParams(-1,dp(26)));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int n,boolean user){if(user)elapsed.setText(clock(SoundCloudPlayback.duration()*n/1000));}public void onStartTrackingTouch(SeekBar s){dragging=true;}public void onStopTrackingTouch(SeekBar s){SoundCloudPlayback.seek(s.getProgress()/1000f);dragging=false;}});
  LinearLayout times=new LinearLayout(c);elapsed=text(c,"0:00",12,false,MUTED);total=text(c,"0:00",12,false,MUTED);total.setGravity(Gravity.RIGHT);times.addView(elapsed,new LinearLayout.LayoutParams(0,-2,1));times.addView(total,new LinearLayout.LayoutParams(0,-2,1));box.addView(times);
  LinearLayout controls=new LinearLayout(c);controls.setGravity(Gravity.CENTER);controls.setPadding(0,dp(18),0,dp(20));box.addView(controls);controls.addView(icon(c,"previous","Предыдущий",TEXT,()->SoundCloudPlayback.next(c,-1)),new LinearLayout.LayoutParams(dp(56),dp(56)));play=icon(c,"play","Пауза или воспроизведение",BG,SoundCloudPlayback::toggle);play.setPadding(dp(25),dp(25),dp(25),dp(25));play.setBackground(touch(TEXT,48));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(dp(82),dp(82));pp.setMargins(dp(26),0,dp(26),0);controls.addView(play,pp);controls.addView(icon(c,"next","Следующий",TEXT,()->SoundCloudPlayback.next(c,1)),new LinearLayout.LayoutParams(dp(56),dp(56)));
  LinearLayout actions=new LinearLayout(c);box.addView(actions);action(actions,"plus","В плейлист",()->SoundCloudCollectionActions.add(this,SoundCloudPlayback.current));action(actions,"queue","Очередь",()->showQueue(c));
  nextCard=new LinearLayout(c);nextCard.setGravity(Gravity.CENTER_VERTICAL);nextCard.setPadding(dp(12),dp(12),dp(8),dp(12));nextCard.setBackground(touch(SURFACE,18));LinearLayout.LayoutParams nl=new LinearLayout.LayoutParams(-1,dp(80));nl.topMargin=dp(20);box.addView(nextCard,nl);nextArt=cover(c,9,null);nextCard.addView(nextArt,new LinearLayout.LayoutParams(dp(52),dp(52)));LinearLayout nextLabels=new LinearLayout(c);nextLabels.setOrientation(1);nextLabels.setPadding(dp(12),0,0,0);nextCard.addView(nextLabels,new LinearLayout.LayoutParams(0,-2,1));nextName=text(c,"",14,true,TEXT);nextName.setSingleLine(true);nextName.setEllipsize(android.text.TextUtils.TruncateAt.END);nextArtist=text(c,"",12,false,MUTED);nextArtist.setSingleLine(true);nextArtist.setPadding(0,dp(6),0,0);nextLabels.addView(nextName);nextLabels.addView(nextArtist);nextCard.addView(icon(c,"chevron","Очередь",MUTED,()->showQueue(c)),new LinearLayout.LayoutParams(dp(40),dp(40)));nextCard.setOnClickListener(v->showQueue(c));
  fragmentView=scroll;refresh();return scroll;
 }
 private void action(LinearLayout row,String type,String label,Runnable click){Context c=row.getContext();LinearLayout b=new LinearLayout(c);b.setGravity(Gravity.CENTER);b.setBackground(touch(android.graphics.Color.TRANSPARENT,14));row.addView(b,new LinearLayout.LayoutParams(0,dp(46),1));ImageView mark=icon(c,type,label,MUTED,click);mark.setPadding(dp(7),dp(7),dp(7),dp(7));b.addView(mark,new LinearLayout.LayoutParams(dp(32),dp(32)));TextView name=text(c,label,13,true,MUTED);b.addView(name);b.setOnClickListener(v->click.run());}
 private void showQueue(Context c){ArrayList<SoundCloudPublic.Track> q=SoundCloudPlayback.queueSnapshot();String[] labels=new String[q.size()];for(int i=0;i<q.size();i++)labels[i]=q.get(i).title+" · "+q.get(i).artist;new AlertDialog.Builder(c).setTitle("Очередь").setItems(labels,(d,w)->SoundCloudPlayback.play(c,q,q.get(w))).setNegativeButton("Закрыть",null).show();}
 private String clock(long ms){long s=Math.max(0,ms/1000);return String.format(java.util.Locale.ROOT,"%d:%02d",s/60,s%60);}
 private void refresh(){if(title==null)return;SoundCloudPublic.Track t=SoundCloudPlayback.current;if(t==null){title.setText("Нет активного трека");status.setText("SoundCloud");nextCard.setVisibility(View.GONE);return;}title.setText(t.title);artist.setText(t.artist);favorite.setImageDrawable(new ClaudMusicIcon(SoundCloudLibrary.contains(currentAccount,"favorites",t.id)?"heartFilled":"heart",ACCENT));if(!shown.equals(t.id)){shown=t.id;art.setTag(null);art.setBackground(new ClaudMusicStyle.Cover());SoundCloudArtwork.bind(art,ClaudMusicStyle.large(t.artwork));}long duration=SoundCloudPlayback.duration();if(!dragging){seek.setProgress(duration<=0?0:(int)Math.min(1000,SoundCloudPlayback.position()*1000/duration));elapsed.setText(clock(SoundCloudPlayback.position()));}total.setText(clock(duration));play.setImageDrawable(new ClaudMusicIcon(SoundCloudPlayback.paused()?"play":"pause",BG));status.setText(SoundCloudPlayback.error!=null?SoundCloudPlayback.error:SoundCloudPlayback.loading()?"Подключение…":"SoundCloud");SoundCloudPublic.Track next=SoundCloudPlayback.nextTrack();nextCard.setVisibility(next==null?View.GONE:View.VISIBLE);if(next!=null){nextName.setText(next.title);nextArtist.setText("Далее · "+next.artist);if(!shownNext.equals(next.id)){shownNext=next.id;nextArt.setTag(null);nextArt.setBackground(new ClaudMusicStyle.Cover());SoundCloudArtwork.bind(nextArt,ClaudMusicStyle.large(next.artwork));}}}
 @Override public void onResume(){super.onResume();active=true;handler.removeCallbacks(tick);handler.post(tick);}
 @Override public void onPause(){active=false;handler.removeCallbacks(tick);super.onPause();}
 @Override public void onFragmentDestroy(){active=false;handler.removeCallbacks(tick);title=null;super.onFragmentDestroy();}
}
